import{_ as t,c as r,o as a,ag as i}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"FPV sUAS","description":"","frontmatter":{"title":"FPV sUAS"},"headers":[],"relativePath":"general/fpv-suas.md","filePath":"general/fpv-suas.md","lastUpdated":null}'),o={name:"general/fpv-suas.md"};function s(n,e,l,p,c,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="fpv-suas" tabindex="-1">FPV sUAS <a class="header-anchor" href="#fpv-suas" aria-label="Permalink to &quot;FPV sUAS&quot;">​</a></h1><h3 id="start-fpv-flying" tabindex="-1">Start FPV Flying <a class="header-anchor" href="#start-fpv-flying" aria-label="Permalink to &quot;Start FPV Flying&quot;">​</a></h3><p>First-person view (FPV) flying offers an immersive experience, piloting drones from the perspective of the cockpit. This guide covers everything beginners need to know about equipment, simulators, and initial flights, drawing from community insights and recommended practices.</p><p><strong>Community Contacts:</strong> Justin C., Bryan S., Stanislav Oros, Lito, Flo.</p><h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>This guide walks new pilots through simulators, gear selection, first flights, drills, strike‐net training, and community resources to accelerate safe, confident FPV flying.</p><h3 id="simulators" tabindex="-1">Simulators <a class="header-anchor" href="#simulators" aria-label="Permalink to &quot;Simulators&quot;">​</a></h3><p>Simulators let you hone throttle, stick control, and orientation without risk of real‐world damage.</p><p><em>Note: You’ll need a compatible radio controller—see Equipment section below.</em></p><ul><li><p><strong>Liftoff</strong> – Realistic physics, beginner-to-advanced modes. <a href="https://store.steampowered.com/app/410340/Liftoff_FPV_Drone_Racing/" target="_blank" rel="noreferrer">FPV Drone Racing on Steam</a></p></li><li><p><strong>Velocidrone</strong> – Custom environments, wide controller support; available from the publisher. <a href="https://www.velocidrone.com/" target="_blank" rel="noreferrer">Velocidrone official site</a></p></li></ul><h3 id="equipment-to-buy" tabindex="-1">Equipment to Buy <a class="header-anchor" href="#equipment-to-buy" aria-label="Permalink to &quot;Equipment to Buy&quot;">​</a></h3><p>Choosing the right gear ensures reliable, enjoyable flights:</p><ul><li><p><strong>Radio Controller</strong> – e.g. RadioMaster Boxer with ELRS internal module for low latency. <a href="https://www.radiomasterrc.com/products/boxer-radio-controller-m2" target="_blank" rel="noreferrer">RadioMaster Boxer ELRS</a></p></li><li><p><strong>Goggles</strong></p><ul><li>HDZero Race Bundle – Balanced cost/performance for digital FPV. <a href="https://www.hd-zero.com/product-page/race-bundle" target="_blank" rel="noreferrer">HDZero Race Bundle</a></li><li>DJI Goggles 2 – Premium clarity; HDMI input; higher price point. <a href="https://www.dji.com/dji-goggles-2" target="_blank" rel="noreferrer">DJI Goggles 2</a></li></ul></li><li><p><strong>Drones</strong></p><ul><li>Tiny Whoops (1S) – Indoor micro quads for initial learning. <a href="https://pyrodrone.com/products/sub250-whoopfly16-1-6-ultra-light-hdzero-1s-tiny-whoop-choose-receiver" target="_blank" rel="noreferrer">Sub250 WhoopFly Ultra-Light</a></li><li>Outdoor 6S HD – e.g. ProTek35 V1.4 O3 for mixed-environment flights. <a href="https://shop.iflight.com/ProTek35-V1.4-O3-6S-HD-Pro2033" target="_blank" rel="noreferrer">ProTek35 V1.4 O3 6S HD</a></li></ul></li><li><p><strong>Batteries &amp; Charger</strong> – Multiple batteries; fast-charge capable.</p></li><li><p><strong>Propellers &amp; Tools</strong> – Spare props, hex drivers, zip-ties, Velcro straps.</p></li></ul><h3 id="your-first-fpv-experience" tabindex="-1">Your First FPV Experience <a class="header-anchor" href="#your-first-fpv-experience" aria-label="Permalink to &quot;Your First FPV Experience&quot;">​</a></h3><p>Start with ~20 hours in a simulator before real flights; this eases the transition and reduces crash rates.</p><h3 id="community-training" tabindex="-1">Community &amp; Training <a class="header-anchor" href="#community-training" aria-label="Permalink to &quot;Community &amp; Training&quot;">​</a></h3><p>Tap into shared knowledge and tutorials:</p><ul><li><p>Joshua Bardwell’s YouTube Channel: <a href="https://www.youtube.com/channel/UCX3eufnI7A2I7IkKHZn8KSQ" target="_blank" rel="noreferrer">Joshua Bardwell</a></p></li><li><p>FPV forums, Discords, local meetup groups</p></li></ul><h3 id="fpv-drills-practices" tabindex="-1">FPV Drills &amp; Practices <a class="header-anchor" href="#fpv-drills-practices" aria-label="Permalink to &quot;FPV Drills &amp; Practices&quot;">​</a></h3><p>Structured drills accelerate skill growth.</p><h3 id="for-beginners" tabindex="-1">For Beginners <a class="header-anchor" href="#for-beginners" aria-label="Permalink to &quot;For Beginners&quot;">​</a></h3><ul><li><p><strong>Box Pattern</strong> – Fly a square to practice orientation.</p></li><li><p><strong>Hovering</strong> – Maintain altitude at various heights.</p></li><li><p><strong>Figure 8s</strong> – Combine turns for coordinated flight.</p></li><li><p><strong>Slow &amp; Hover</strong> – Reduce speed into a steady hover.</p></li></ul><h3 id="for-advanced-pilots" tabindex="-1">For Advanced Pilots <a class="header-anchor" href="#for-advanced-pilots" aria-label="Permalink to &quot;For Advanced Pilots&quot;">​</a></h3><ul><li><p><strong>Orbits</strong> – Circle a fixed point smoothly.</p></li><li><p><strong>Shooting Gaps</strong> – Navigate tight openings (doors, trees).</p></li><li><p><strong>Fixed-Bearing Decreasing-Range</strong> – Approach a target on a constant bearing.</p></li><li><p><strong>FPV Tag</strong> – Chase moving objects for agility.</p></li></ul><h3 id="specialty-drills" tabindex="-1">Specialty Drills <a class="header-anchor" href="#specialty-drills" aria-label="Permalink to &quot;Specialty Drills&quot;">​</a></h3><ul><li><p><strong>Angle Mode</strong> – Stabilized flight for indoor/data-capture missions.</p></li><li><p><strong>Acro Mode</strong> – Manual control without stabilization, essential for freestyle/racing.</p></li></ul><h3 id="crash-nets-for-fpv-strike-training" tabindex="-1">Crash Nets for FPV Strike Training <a class="header-anchor" href="#crash-nets-for-fpv-strike-training" aria-label="Permalink to &quot;Crash Nets for FPV Strike Training&quot;">​</a></h3><p>Crash nets (or “strike nets”) contain drones during impact-practice drills, safeguarding gear and pilots while marking clear targets.</p><h3 id="recommended-products" tabindex="-1">Recommended Products <a class="header-anchor" href="#recommended-products" aria-label="Permalink to &quot;Recommended Products&quot;">​</a></h3><ul><li><p><strong>SKLZ Quickster 7×7 Net</strong> – 7′×7′ pop-up soccer net; portable. <a href="https://www.big5sportinggoods.com/store/details/sklz-quickster-7-x-7-net/" target="_blank" rel="noreferrer">Big5 Sporting Goods</a></p></li><li><p><strong>Go Time Gear Twister Pop-Up Goal</strong> – 6′×4′; sets up in seconds. <a href="https://www.big5sportinggoods.com/store/details/go-time-gear-6-ft-twister-pop-up-soccer-goal/" target="_blank" rel="noreferrer">Big5 Sporting Goods</a></p></li><li><p><strong>Go Time Gear Equator Goal</strong> – 14′×6.5′ batting-cage style for advanced strikes. <a href="https://www.big5sportinggoods.com/store/details/go-time-gear-equator-easy-set-up-soccer-goal/" target="_blank" rel="noreferrer">Big5 Sporting Goods</a></p></li><li><p><strong>Pugg Soccer Weighted Nets</strong> – Base-weighted, no stakes needed.</p></li><li><p><strong>Batting Cage Nets</strong> – Heavy-duty, full-coverage netting.</p></li></ul><h3 id="community-tips-variations" tabindex="-1">Community Tips &amp; Variations <a class="header-anchor" href="#community-tips-variations" aria-label="Permalink to &quot;Community Tips &amp; Variations&quot;">​</a></h3><ul><li><p>Aim small, miss small – use smaller nets until trainees consistently hit 7×7′ targets.</p></li><li><p>White-sheet targets – drape a sheet with painted bullseyes over a rover for &lt;$10 setup.</p></li><li><p>Budget nets – inexpensive nets can be cut to custom shapes and are locally available.</p></li></ul><h3 id="diy-setup" tabindex="-1">DIY Setup <a class="header-anchor" href="#diy-setup" aria-label="Permalink to &quot;DIY Setup&quot;">​</a></h3><h2 id="construct-a-2×4-box-frame-matching-your-mock-vehicle" tabindex="-1">Construct a 2×4 box frame matching your mock vehicle. <a class="header-anchor" href="#construct-a-2×4-box-frame-matching-your-mock-vehicle" aria-label="Permalink to &quot;Construct a 2×4 box frame matching your mock vehicle.&quot;">​</a></h2><h2 id="attach-the-pop-up-net-with-zip-ties-or-bungees" tabindex="-1">Attach the pop-up net with zip-ties or bungees. <a class="header-anchor" href="#attach-the-pop-up-net-with-zip-ties-or-bungees" aria-label="Permalink to &quot;Attach the pop-up net with zip-ties or bungees.&quot;">​</a></h2><h2 id="mark-strike-zones-using-spray-paint-or-target-stickers" tabindex="-1">Mark strike zones using spray-paint or target stickers. <a class="header-anchor" href="#mark-strike-zones-using-spray-paint-or-target-stickers" aria-label="Permalink to &quot;Mark strike zones using spray-paint or target stickers.&quot;">​</a></h2><h2 id="adjust-distance-and-angle-to-simulate-different-attack-profiles" tabindex="-1">Adjust distance and angle to simulate different attack profiles. <a class="header-anchor" href="#adjust-distance-and-angle-to-simulate-different-attack-profiles" aria-label="Permalink to &quot;Adjust distance and angle to simulate different attack profiles.&quot;">​</a></h2><h3 id="community-insights" tabindex="-1">Community Insights <a class="header-anchor" href="#community-insights" aria-label="Permalink to &quot;Community Insights&quot;">​</a></h3><p>HD FPV options each have trade-offs: DJI leads in performance but at higher cost and regulatory risk; Walksnail/Caddx respond to feedback and supply 1S ultra-light systems; HDZero is a mid-tier choice.</p><h3 id="additional-tips" tabindex="-1">Additional Tips <a class="header-anchor" href="#additional-tips" aria-label="Permalink to &quot;Additional Tips&quot;">​</a></h3><ul><li><p><strong>Budgeting</strong> – Plan for gear, repairs, and upgrades: “Cry once, fly forever.”</p></li><li><p><strong>Safety</strong> – Follow local regulations and best practices; see <a href="/general/suas.html">Certifications</a>.</p></li><li><p><strong>Encryption</strong> – Consider ELRS forks like PrivacyLRS for link encryption: <a href="https://github.com/sensei-hacker/PrivacyLRS" target="_blank" rel="noreferrer">https://github.com/sensei-hacker/PrivacyLRS</a></p></li></ul><p>[Piloting] [Equipment] [Simulators] [Training] [Simulators] [Systems]</p>',42)])])}const g=t(o,[["render",s]]);export{u as __pageData,g as default};
